arguments.command:
python3 - <<'EOF'
import sys, json
sys.path.insert(0, "/app/categorizationapp")
from categorizationapp import app
c = app.test_client()

def call(bank, acc, txns):
    payload = {"bank": bank, "acc_type": acc, "accountUID": "u1",
               "accountHolder": "Test User", "isPFMEnabled": False,
               "transactions": txns}
    r = c.post("/categorizeTransaction", json=payload)
    assert r.status_code == 200, r.data
    return r.get_json()["response"]

def tx(desc, remark, typ, amt):
    return {"description": desc, "remark": remark, "type": typ,
            "amount": amt, "balanceAfterTransaction": 1000,
            "transactionTimestamp": "2026-07-01T10:00:00"}

out = call("IDBI", "SAVING", [
    tx("ACH-BD-NACH-ACME INDUSTRIES", "", "CREDIT", 55000),
    tx("GBHDL0123456789 RAVI KUMAR", "", "CREDIT", 12000),
])
for t in out:
    print("IDBI:", t["description"], "->", t["transactionCategory"], "|", t["partyName"])

out = call("INDUSIND", "SAVING", [
    tx("MR SHARMA", "123456", "DEBIT", 5000),
    tx("POS TXN- BIG BAZAAR MID012345", "", "CREDIT", 2500),
])
for t in out:
    print("INDUSIND:", t["description"], "->", t["transactionCategory"], "|", t["partyName"])

out = call("BANK_OF_MAHARASHTRA", "SAVING", [
    tx("NACH MANDATE VERIFICATION", "", "DEBIT", 1),
])
for t in out:
    print("BOM:", t["description"], "->", t["transactionCategory"], "|", t["partyName"])
EOF

